files./etc/nginx/sites-enabled/b_reverse_proxy:
# /etc/nginx/sites-available/b_reverse_proxy

# ============================================================
# WebSocket 升级头动态映射
# 仅当客户端请求 Upgrade 时才发送 "upgrade"，否则发送 "close"
# 这是修复"转圈圈"问题的关键一步
# ============================================================
map $http_upgrade $connection_upgrade {
    default upgrade;
    ''      close;
}

# ============================================================
# HTTP 反向代理 (端口 80)
# 将 10.130.96.101:80 的请求转发到设备B的 8080 端口
# ============================================================
server {
    listen 80;
    server_name _;

    access_log /var/log/nginx/b_access.log;
    error_log  /var/log/nginx/b_error.log;

    location / {
        proxy_pass http://192.168.127.10:8080;

        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;

        # 超时设置
        proxy_connect_timeout 10s;
        proxy_read_timeout    60s;
        proxy_send_timeout    60s;

        # HTTP/1.1 + WebSocket 支持
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection $connection_upgrade;

        # 关闭缓冲，适配实时数据推送
        proxy_buffering off;
        proxy_request_buffering off;
    }
}

# ============================================================
# WebSocket 代理: Config + AMR/State (端口 6001)
# ============================================================
server {
    listen 6001;
    server_name _;

    access_log /var/log/nginx/b_ws_6001_access.log;
    error_log  /var/log/nginx/b_ws_6001_error.log;

    location / {
        proxy_pass http://192.168.127.10:6001;

        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;

        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection $connection_upgrade;

        # WebSocket 长连接，超时设为 24 小时
        proxy_read_timeout 86400s;
        proxy_send_timeout 86400s;

        proxy_buffering off;
    }
}

# ============================================================
# WebSocket 代理: Alarm (端口 6004)
# ============================================================
server {
    listen 6004;
    server_name _;

    access_log /var/log/nginx/b_ws_6004_access.log;
    error_log  /var/log/nginx/b_ws_6004_error.log;

    location / {
        proxy_pass http://192.168.127.10:6004;

        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;

        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection $connection_upgrade;

        proxy_read_timeout 86400s;
        proxy_send_timeout 86400s;

        proxy_buffering off;
    }
}
